245	// serverForFile finds which configured server handles file's extension. It
246	// is the whole check for a tool that asks about a file rather than about a
247	// position in it, since such a tool has no line or column to validate.
248	func (e *editor) serverForFile(file string) (string, error) {
249		ext := filepath.Ext(file)
250		name, ok := e.serverForExt[ext]
251		if !ok {
252			return "", fmt.Errorf("no configured language server for file extension %q", ext)
253		}
254		return name, nil
255	}
