257	func toLocationsOutput(locations []lsp.Location) locationsOutput {
258		out := locationsOutput{Locations: make([]location, len(locations))}
259		for i, loc := range locations {
260			out.Locations[i] = location{File: loc.File, Line: loc.Line, Column: loc.Column}
261		}
262		return out
263	}
