265	func toDiagnosticsOutput(diagnostics []lsp.Diagnostic) diagnosticsOutput {
266		out := diagnosticsOutput{Diagnostics: make([]diagnostic, len(diagnostics))}
267		for i, d := range diagnostics {
268			out.Diagnostics[i] = diagnostic{
269				StartLine:   d.StartLine,
270				StartColumn: d.StartColumn,
271				EndLine:     d.EndLine,
272				EndColumn:   d.EndColumn,
273				Severity:    d.Severity,
274				Message:     d.Message,
275				Source:      d.Source,
276				Code:        d.Code,
277			}
278		}
279		return out
280	}
281	
282	func toSignatureHelpOutput(help lsp.SignatureHelp) signatureHelpOutput {
283		out := signatureHelpOutput{
284			Signatures:      make([]signature, len(help.Signatures)),
285			ActiveSignature: help.ActiveSignature,
286			ActiveParameter: help.ActiveParameter,
287		}
288		for i, s := range help.Signatures {
289			out.Signatures[i] = signature{
290				Label:         s.Label,
291				Documentation: s.Documentation,
292				Parameters:    s.Parameters,
293			}
294		}
295		return out
296	}
297	
298	func toEditsOutput(edits []lsp.Edit) editsOutput {
299		out := editsOutput{Edits: make([]edit, len(edits))}
300		for i, e := range edits {
301			out.Edits[i] = edit{
302				File:        e.File,
303				StartLine:   e.StartLine,
304				StartColumn: e.StartColumn,
305				EndLine:     e.EndLine,
306				EndColumn:   e.EndColumn,
307				NewText:     e.NewText,
308			}
309		}
310		return out
311	}
